"""Résumé de séance d'entraînement — projet de fin de chapitre 1."""

MET = {"course": 9.8, "velo": 7.5}


# ---------- Saisies validées ----------

def saisie_entier(message, mini, maxi):
    while True:
        saisie = input(message).strip()
        if not saisie.isdigit():
            print("Entre un nombre entier.")
            continue
        valeur = int(saisie)
        if not mini <= valeur <= maxi:
            print(f"Valeur attendue entre {mini} et {maxi}.")
            continue
        return valeur


def saisie_flottant(message, mini, maxi):
    while True:
        saisie = input(message).strip()
        if not saisie.replace(".", "", 1).isdigit():   # tolère UN point
            print("Entre un nombre (ex. 9.5).")
            continue
        valeur = float(saisie)
        if not mini <= valeur <= maxi:
            print(f"Valeur attendue entre {mini} et {maxi}.")
            continue
        return valeur


def saisie_choix(message, choix_valides):
    while True:
        saisie = input(message).strip().lower()
        if saisie in choix_valides:
            return saisie
        print(f"Choix possibles : {', '.join(choix_valides)}")


# ---------- Métier (fonctions pures) ----------

def vitesse_kmh(distance_km, duree_min):
    return distance_km / (duree_min / 60)


def allure_min_km(distance_km, duree_min):
    allure_s = duree_min * 60 / distance_km
    return int(allure_s // 60), int(allure_s % 60)


def zone_cardiaque(fc, fc_max):
    ratio = fc / fc_max
    if ratio >= 0.9:
        return 5
    if ratio >= 0.8:
        return 4
    if ratio >= 0.7:
        return 3
    if ratio >= 0.6:
        return 2
    return 1


def calories(sport, poids_kg, duree_min):
    return MET[sport] * poids_kg * (duree_min / 60)


# ---------- Présentation ----------

def formater_resume(sport, duree_min, distance_km, fc, age, poids_kg):
    fc_max = 220 - age
    h, m = divmod(duree_min, 60)
    lignes = [
        "===== Résumé de séance =====",
        f"{'Sport':<10} : {sport}",
        f"{'Durée':<10} : {h} h {m:02d}",
        f"{'Distance':<10} : {distance_km:.1f} km",
        f"{'Vitesse':<10} : {vitesse_kmh(distance_km, duree_min):.2f} km/h",
    ]
    if sport == "course":
        amin, asec = allure_min_km(distance_km, duree_min)
        lignes.append(f"{'Allure':<10} : {amin}:{asec:02d} min/km")
    lignes.append(
        f"{'FC':<10} : {fc} bpm → zone {zone_cardiaque(fc, fc_max)}"
        f" ({fc / fc_max:.0%} FCmax)"
    )
    lignes.append(f"{'Calories':<10} : ~{calories(sport, poids_kg, duree_min):.0f} kcal")
    lignes.append("============================")
    return "\n".join(lignes)


# ---------- Orchestration ----------

def main():
    sport = saisie_choix("Sport (course/velo) : ", MET.keys())
    duree = saisie_entier("Durée (minutes)     : ", 1, 600)
    distance = saisie_flottant("Distance (km)       : ", 0.1, 400)
    fc = saisie_entier("FC moyenne (bpm)    : ", 60, 220)
    age = saisie_entier("Âge                 : ", 10, 100)
    poids = saisie_entier("Poids (kg)          : ", 30, 200)
    print()
    print(formater_resume(sport, duree, distance, fc, age, poids))


if __name__ == "__main__":
    main()
```

Points d'architecture — c'est eux qu'il faut retenir, plus que les formules :

- **Saisie / métier / présentation séparés.** Les fonctions métier sont pures (testables au chapitre 7 sans simuler un clavier).
- Le dict `MET` sert deux fois : validation des sports ET coefficient — une seule source de vérité.
- Le résumé est construit en **liste de lignes** jointes à la fin : la ligne conditionnelle (Allure) s'insère naturellement.
- Bonus boucle de sessions : envelopper le corps de `main()` dans `while True:` et sortir si `saisie_choix("Nouvelle séance ? (o/n) : ", ("o", "n")) == "n"`, en cumulant `distance` dans un total.
